using Ginecologia.Modules.Promociones.Application;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
namespace Ginecologia.Modules.Promociones.Infrastructure;
public sealed class BirthdayPromotionBackgroundService(IServiceScopeFactory scopeFactory, ILogger<BirthdayPromotionBackgroundService> logger) : BackgroundService
{ private static readonly TimeZoneInfo Nicaragua = TimeZoneInfo.FindSystemTimeZoneById("America/Managua"); protected override async Task ExecuteAsync(CancellationToken stoppingToken) { while (!stoppingToken.IsCancellationRequested) { var now = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, Nicaragua); var nextMidnightLocal = DateTime.SpecifyKind(now.Date.AddDays(1), DateTimeKind.Unspecified); var nextMidnightUtc = TimeZoneInfo.ConvertTimeToUtc(nextMidnightLocal, Nicaragua); await Task.Delay(nextMidnightUtc - DateTime.UtcNow, stoppingToken); try { using var scope = scopeFactory.CreateScope(); var useCase = scope.ServiceProvider.GetRequiredService<GenerateBirthdayPromotionsUseCase>(); var today = DateOnly.FromDateTime(TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, Nicaragua)); var generated = await useCase.ExecuteAsync(today, stoppingToken); logger.LogInformation("Se generaron {Count} promociones de cumpleaños.", generated); } catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested) { } catch (Exception ex) { logger.LogError(ex, "Error al generar promociones de cumpleaños."); } } } }
